const PREFIX = 'rusya-gezisi-';
const CACHE = `${PREFIX}${VERSION}`;
// Every version's cache also stores its FILES under this key, so a later version can tell which copies are still current.
const MANIFEST = '__files.json';
const PARALLEL = 6;
const EXACT = { ignoreVary: true };

self.addEventListener('install', (event) => {
  // Only a first install has something to show; an update runs quietly behind the working version.
  const firstInstall = !self.registration.active;
  event.waitUntil(precache(firstInstall).catch(async (error) => {
    await broadcast({ type: firstInstall ? 'error' : 'update-error', message: String(error) });
    throw error;
  }));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter((name) => name.startsWith(PREFIX) && name !== CACHE).map((name) => caches.delete(name)));
    await self.clients.claim();
    await broadcast({ type: 'ready', total: FILES.length, version: VERSION });
  })());
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'skip-waiting') self.skipWaiting();
  if (event.data?.type === 'status') event.waitUntil(reportStatus(event.source));
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
  event.respondWith(fromCache(request));
});

function scoped(path) {
  return new URL(path, self.registration.scope);
}

// Resumable: files already in this version's cache are skipped, so an interrupted install picks up where it stopped.
// Incremental: a file whose hash an earlier version also listed is copied from that version's cache, not downloaded.
async function precache(announce) {
  const cache = await caches.open(CACHE);
  await cache.put(scoped(MANIFEST), new Response(JSON.stringify(Object.fromEntries(FILES)), {
    headers: { 'Content-Type': 'application/json' },
  }));
  const earlier = await earlierCaches();
  const queue = [...FILES];
  const abort = new AbortController();
  let failure = null;
  let done = 0;
  const worker = async () => {
    while (queue.length && !failure) {
      const [path, hash] = queue.shift();
      try {
        await store(cache, earlier, path, hash, abort.signal);
      } catch (error) {
        // The first failure ends the install: stop the other downloads so they cannot report progress over it.
        failure ??= error;
        abort.abort();
        return;
      }
      done += 1;
      if (announce && !failure && (done % 25 === 0 || done === FILES.length)) {
        await broadcast({ type: 'progress', done, total: FILES.length });
      }
    }
  };
  await Promise.all(Array.from({ length: PARALLEL }, worker));
  if (failure) throw failure;
}

async function store(cache, earlier, path, hash, signal) {
  const url = scoped(path);
  if (await cache.match(url, EXACT)) return;
  for (const { cache: old, hashes } of earlier) {
    if (hashes[path] !== hash) continue;
    const copy = await old.match(url, EXACT);
    if (copy) {
      await cache.put(url, copy);
      return;
    }
  }
  await cache.put(url, await download(url, signal));
}

async function download(url, signal) {
  const response = await fetch(url, { cache: 'reload', signal });
  if (!response.ok) throw new Error(`${url.pathname}: HTTP ${response.status}`);
  if (!response.redirected) return response;
  // Browsers refuse a redirected response as the answer to a navigation, so keep a plain copy.
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers: response.headers });
}

// Newest first. A cache without a readable manifest (a build from before manifests) is never trusted.
async function earlierCaches() {
  const names = (await caches.keys()).filter((name) => name.startsWith(PREFIX) && name !== CACHE).reverse();
  const found = [];
  for (const name of names) {
    const cache = await caches.open(name);
    const hashes = await cache.match(scoped(MANIFEST), EXACT)
      .then((response) => response?.json())
      .catch(() => null);
    if (hashes && typeof hashes === 'object') found.push({ cache, hashes });
  }
  return found;
}

async function fromCache(request) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(request, { ignoreSearch: true, ignoreVary: true });
  if (hit) return hit;
  if (request.mode === 'navigate') {
    const page = await cache.match(scoped('./'), EXACT);
    if (page) return page;
  }
  try {
    return await fetch(request);
  } catch {
    return new Response('Çevrimdışı: bu dosya cihazda yok.', { status: 503, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
  }
}

async function reportStatus(client) {
  const cache = await caches.open(CACHE);
  const stored = new Set((await cache.keys()).map((request) => request.url));
  const done = FILES.filter(([path]) => stored.has(scoped(path).href)).length;
  const message = done === FILES.length
    ? { type: 'ready', total: FILES.length, version: VERSION }
    : { type: 'progress', done, total: FILES.length };
  client?.postMessage(message);
}

async function broadcast(message) {
  const clients = await self.clients.matchAll({ includeUncontrolled: true, type: 'window' });
  clients.forEach((client) => client.postMessage(message));
}
